"""Compute integer division for the fixture."""
def solve(a, b):
    """Return the intended integer floor quotient."""
    return int(a / b)

"""Deduplicate ordered integer values."""
def solve(values):
    """Return values in their intended first-occurrence order."""
    return sorted(set(values))

"""Count normalized whitespace-delimited words."""
def solve(text):
    """Return intended casefolded word frequencies."""
    counts = {}
    for word in text.lower().split(' '):
        counts[word] = counts.get(word, 0) + 1
    return counts

"""Clamp integers into an inclusive interval."""
def solve(value, low, high):
    """Return the intended bounded integer value."""
    return min(low, max(high, value))
